<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to rewrite:
<original_code>
package com.animal.demo;import java.util.*;
public class Animal {
    public static void main(String []arg){
        Scanner scanner=new Scanner(System.in);
        int n=scanner.nextInt();long ans=0;
        //StringBuilder sb=new StringBuilder();
        long mod=1000000007;
        //System.out.println(qmod(2,3,mod));
        ans=(getc(n+1,mod)-getc(n,mod)+mod)%mod;
        ans=qmod(3,n-1,mod);
        System.out.println(ans);
        //System.out.print(sb);
    }
    static long getc(long n,long mod){
        long res=1;
        long tem=1;
        for(long i=n+1;i<=2*n;i++)
            res=res*i%mod;
        for(int i=1;i<=n;i++)
            tem=tem*i;
        tem=qmod(tem,mod-2,mod);
        res=res*tem%mod*qmod(n+1,mod-2,mod);
        return res%mod;
    }
    static long qmod(long a,long b,long mod){
        long res=1;
        while(b!=0){
            if((b&1)!=0)res=res*a%mod;
            a=a*a%mod;b>>=1;
        }return res;
    }
}

